{
  "name": "library-skills",
  "version": "0.0.19",
  "description": "Library Skills, AI Agents using libraries, as intended, always up to date.",
  "type": "module",
  "exports": {
    ".": {
      "types": "./ts/dist/index.d.ts",
      "default": "./ts/dist/index.js"
    }
  },
  "main": "./ts/dist/index.js",
  "module": "./ts/dist/index.js",
  "types": "./ts/dist/index.d.ts",
  "bin": {
    "library-skills": "ts/dist/cli.js"
  },
  "files": [
    "ts/dist",
    "ts/src/tool_skill"
  ],
  "scripts": {
    "build": "tsup",
    "dev": "tsup --watch",
    "prepublishOnly": "npm run build",
    "test:ts": "vitest run --coverage",
    "typecheck": "tsc --noEmit"
  },
  "author": {
    "name": "Sebastián Ramírez",
    "email": "tiangolo@gmail.com"
  },
  "license": "MIT",
  "devDependencies": {
    "@types/node": "^25.6.0",
    "@vitest/coverage-v8": "^4.1.5",
    "tsup": "^8.4.0",
    "typescript": "^6.0.3",
    "vitest": "^4.1.5"
  },
  "dependencies": {
    "@inquirer/checkbox": "^5.1.4",
    "commander": "^15.0.0",
    "csv-parse": "^6.2.1",
    "smol-toml": "^1.6.1",
    "yaml": "^2.4.2"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/tiangolo/library-skills.git"
  }
}

{
  "name": "my-react-app",
  "version": "0.1.0",
  "private": true,
  "dependencies": {
    "react": "^16.4.1",
    "react-dom": "^16.4.1",
    "react-scripts": "1.1.4"
  },
  "scripts": {
    "start": "react-scripts start",
    "build": "react-scripts build",
    "test": "react-scripts test --env=jsdom",
    "eject": "react-scripts eject"
  }
}
